&lt;p&gt;&lt;strong style=&quot;&quot;&gt;&lt;img alt=&quot;&quot; src=&quot;//storage.googleapis.com/tb-img/production/20/07/F1_Maanik.G_22-07-2020_Savita_D2.png&quot; style=&quot;width: 127px; height: 138px;&quot; /&gt;&lt;/strong&gt;&lt;/p&gt;

