&lt;p&gt;&lt;span style=&quot;&quot;&gt;a&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;+ b&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;+ c&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;+ 48 = 8(a + b + c)&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;a&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;+ b&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;+ c&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;+ 48 = 8(a + b + c) &lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; a&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;-&amp;nbsp;&lt;/span&gt;8a + 16&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size: 10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;-&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;8b&amp;nbsp;+ 16&amp;nbsp;&lt;/span&gt;+ c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size: 10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;-&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;8c&amp;nbsp;+ 16 = 0&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; (a - 4)&lt;sup&gt;2&lt;/sup&gt;&amp;nbsp;+&amp;nbsp;(b&amp;nbsp;- 4)&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt; + (c&amp;nbsp;- 4)&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp; = 0&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Now, sum of squares = 0&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; each term is = 0&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;there4; a - 4 = 0 , b - 4 = 0 and c - 4 = 0&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; a = b = c = 4&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;there4;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(\sqrt[3]{a^3-b^3+c^3}\)&lt;/span&gt;&amp;nbsp;=&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(\sqrt[3]{4^3-4^3+4^3}\)&lt;/span&gt;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;=&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(\sqrt[3]{4^3}\)&lt;/span&gt;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;= 4&lt;/p&gt;

