hn.value:
&lt;p style=&quot;&quot;&gt;&lt;strong&gt;दिया है:&lt;/strong&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;img alt=&quot;&quot; src=&quot;//storage.googleapis.com/tb-img/production/22/08/F6_Madhuri_SSC_20.08.2022_D2.png&quot; style=&quot; width: 198px; height: 133px;&quot; /&gt;&lt;/p&gt;

